import { spawn } from "node:child_process";
import { constants } from "node:fs";
import { copyFile, lstat, mkdtemp, open, rm } from "node:fs/promises";
import { join } from "node:path";
import { sameResourceIdentity } from "./directories.js";
import { mediaSourceIdentity } from "./library.js";

/** Host-only optimization. Both paths are managed storage, never guest paths. */
export async function stageResourceClone(options: {
  sourcePath: string;
  stagingDirectory: string;
  targetDevice: number;
  verify(): Promise<void>;
  signal?: AbortSignal;
}) {
  const { sourcePath, stagingDirectory, signal } = options;
  signal?.throwIfAborted();
  await options.verify();
  signal?.throwIfAborted();
  const source = await lstat(sourcePath);
  if (!source.isFile() || source.isSymbolicLink()) throw new Error("Invalid resource clone source");
  if (source.dev !== options.targetDevice || !["darwin", "linux"].includes(process.platform))
    return undefined;
  const staging = await lstat(stagingDirectory);
  if (!staging.isDirectory() || staging.isSymbolicLink())
    throw new Error("Invalid resource clone staging directory");
  if (staging.dev !== source.dev) return undefined;
  const directory = await mkdtemp(join(stagingDirectory, "clone-"));
  const identity = await lstat(directory);
  const path = join(directory, "content");
  let handle: Awaited<ReturnType<typeof open>> | undefined;
  const verify = async () => {
    signal?.throwIfAborted();
    await options.verify();
    const currentStaging = await lstat(stagingDirectory);
    const currentDirectory = await lstat(directory);
    const currentSource = await lstat(sourcePath);
    if (
      !currentStaging.isDirectory() ||
      currentStaging.isSymbolicLink() ||
      !sameResourceIdentity(currentStaging, staging) ||
      !currentDirectory.isDirectory() ||
      currentDirectory.isSymbolicLink() ||
      !sameResourceIdentity(currentDirectory, identity) ||
      !currentSource.isFile() ||
      currentSource.isSymbolicLink() ||
      Object.entries(mediaSourceIdentity(source)).some(
        ([key, value]) => currentSource[key as keyof typeof source] !== value,
      )
    )
      throw new Error("Resource changed during clone");
    signal?.throwIfAborted();
  };
  const close = async () => {
    await handle?.close().catch(() => {});
    handle = undefined;
    const current = await lstat(directory).catch(() => undefined);
    if (current?.isDirectory() && sameResourceIdentity(current, identity))
      await rm(directory, { recursive: true, force: true }).catch(() => {});
  };
  try {
    await verify();
    try {
      if (process.platform === "darwin") {
        // Electron's Node/libuv does not implement FICLONE on macOS. The OS
        // utility uses clonefile, with ordinary copy fallback on other volumes.
        // Its target is fresh Host-private storage, outside the tool grant.
        await new Promise<void>((resolve, reject) => {
          const child = spawn("/bin/cp", ["-c", "-n", sourcePath, path], {
            stdio: "ignore",
            signal,
          });
          child.once("error", reject);
          child.once("close", (code) => {
            if (code === 0) resolve();
            else reject(new Error("Native resource clone failed"));
          });
        });
      } else {
        // FORCE prevents a failed Linux reflink from silently doing another
        // full copy before the existing streaming fallback is used.
        await copyFile(
          sourcePath,
          path,
          constants.COPYFILE_EXCL | constants.COPYFILE_FICLONE_FORCE,
        );
      }
    } catch (error) {
      await verify();
      if (
        process.platform !== "darwin" &&
        !["ENOSYS", "ENOTSUP", "EOPNOTSUPP", "EXDEV", "EINVAL"].includes(
          (error as NodeJS.ErrnoException).code ?? "",
        )
      )
        throw error;
      await close();
      return undefined;
    }
    await verify();
    handle = await open(
      path,
      constants.O_RDWR | (constants.O_NOFOLLOW ?? 0) | (constants.O_NONBLOCK ?? 0),
    );
    const cloned = await handle.stat();
    if (!cloned.isFile() || cloned.size !== source.size || sameResourceIdentity(cloned, source))
      throw new Error("Invalid cloned resource");
    await handle.chmod(0o600);
    return { path, handle, verify, close };
  } catch (error) {
    await close();
    throw error;
  }
}

import { createHash, randomUUID } from "node:crypto";
import { constants } from "node:fs";
import { lstat, mkdir, open, realpath, rename, rm } from "node:fs/promises";
import { dirname, isAbsolute, join, resolve } from "node:path";
import type { MediaScope } from "./types.js";

export const MAX_MEDIA_JSON_BYTES = 4 * 1024 * 1024;

export function normalizeMediaScope(scope: MediaScope): MediaScope {
  if (!scope || !/^[a-z][a-z0-9-]{0,63}$/.test(scope.appId)) {
    throw new Error("Media operations require a valid Host-bound app ID");
  }
  if (
    typeof scope.projectPath !== "string" ||
    !isAbsolute(scope.projectPath) ||
    scope.projectPath.length > 4096 ||
    scope.projectPath.includes("\0")
  ) {
    throw new Error("Media operations require an absolute Host-bound project path");
  }
  return { appId: scope.appId, projectPath: resolve(scope.projectPath) };
}

export function mediaScopeKey(scope: MediaScope): string {
  const normalized = normalizeMediaScope(scope);
  return createHash("sha256")
    .update("codeshell-media-v1\0")
    .update(normalized.appId)
    .update("\0")
    .update(normalized.projectPath)
    .digest("hex");
}

export async function prepareMediaRoot(root: string): Promise<string> {
  if (!isAbsolute(root)) throw new Error("Media storage root must be absolute");
  await mkdir(root, { recursive: true, mode: 0o700 });
  const info = await lstat(root);
  if (!info.isDirectory() || info.isSymbolicLink())
    throw new Error("Media root must be a real directory");
  return realpath(root);
}

/** Validate each managed descendant instead of following a replaced symlink. */
export async function mediaDirectory(
  root: string,
  segments: string[],
  create = true,
): Promise<string> {
  let directory = await prepareMediaRoot(root);
  for (const segment of segments) {
    if (!/^[a-zA-Z0-9._-]+$/.test(segment) || segment === "." || segment === "..") {
      throw new Error("Invalid managed media directory");
    }
    directory = join(directory, segment);
    if (create)
      await mkdir(directory, { mode: 0o700 }).catch((error: NodeJS.ErrnoException) => {
        if (error.code !== "EEXIST") throw error;
      });
    const info = await lstat(directory);
    if (!info.isDirectory() || info.isSymbolicLink())
      throw new Error("Media directory must not be a symlink");
  }
  return directory;
}

export function cloneMediaJson<T>(value: T, maxBytes = MAX_MEDIA_JSON_BYTES): T {
  let serialized: string | undefined;
  try {
    serialized = JSON.stringify(value);
  } catch {
    throw new Error("Media data must be serializable JSON");
  }
  if (serialized === undefined || Buffer.byteLength(serialized) > maxBytes) {
    throw new Error("Media JSON exceeds its storage budget");
  }
  return JSON.parse(serialized) as T;
}

export async function readMediaJson(file: string): Promise<unknown> {
  const handle = await open(file, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
  try {
    const info = await handle.stat();
    if (!info.isFile() || info.size > MAX_MEDIA_JSON_BYTES)
      throw new Error("Invalid media metadata file");
    return JSON.parse(await handle.readFile("utf8"));
  } finally {
    await handle.close();
  }
}

export async function writeMediaJson(file: string, value: unknown): Promise<void> {
  const serialized = `${JSON.stringify(cloneMediaJson(value))}\n`;
  const temporary = `${file}.${randomUUID()}.tmp`;
  let handle: Awaited<ReturnType<typeof open>> | undefined;
  try {
    handle = await open(temporary, "wx", 0o600);
    await handle.writeFile(serialized);
    await handle.sync();
    await handle.close();
    handle = undefined;
    await rename(temporary, file);
    // Sync the rename on platforms that permit directory file descriptors.
    const directory = await open(dirname(file), "r").catch(() => null);
    if (directory) {
      await directory.sync().catch(() => {});
      await directory.close();
    }
  } finally {
    await handle?.close().catch(() => {});
    await rm(temporary, { force: true }).catch(() => {});
  }
}

import { constants, type Stats } from "node:fs";
import { lstat, mkdir, open, realpath, type FileHandle } from "node:fs/promises";
import { isAbsolute, join } from "node:path";

export function resourceRelativePath(value: unknown): string {
  if (
    typeof value !== "string" ||
    !value ||
    value.length > 1024 ||
    value.split("/").length > 16 ||
    value
      .split("/")
      .some(
        (part) =>
          !part ||
          part === "." ||
          part === ".." ||
          part.length > 240 ||
          /[\\\u0000-\u001f\u007f:]/.test(part) ||
          /[. ]$/.test(part) ||
          /^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|$)/i.test(part),
      )
  )
    throw new Error("Invalid relative resource path");
  return value;
}

export function sameResourceIdentity(
  a: Pick<Stats, "dev" | "ino">,
  b: Pick<Stats, "dev" | "ino">,
): boolean {
  return a.dev === b.dev && a.ino === b.ino;
}

/** Hold every ancestor and verify its name still refers to that exact directory. */
export async function openResourceDirectory(
  root: string,
  path: string,
  create: boolean,
  authorize: () => Promise<void>,
) {
  if (!isAbsolute(root) || root.includes("\0")) throw new Error("Invalid resource directory grant");
  resourceRelativePath(path);
  const parts = path.split("/");
  const name = parts.pop()!;
  const held: { path: string; handle: FileHandle; identity: Stats }[] = [];
  const close = async () => {
    await Promise.all(held.map((entry) => entry.handle.close().catch(() => {})));
  };
  const verify = async () => {
    await authorize();
    for (const entry of held) {
      const current = await lstat(entry.path);
      if (
        !current.isDirectory() ||
        current.isSymbolicLink() ||
        !sameResourceIdentity(current, entry.identity)
      )
        throw new Error("Resource directory changed while it was in use");
    }
    await authorize();
  };
  try {
    await authorize();
    const original = await lstat(root);
    if (!original.isDirectory() || original.isSymbolicLink())
      throw new Error("Resource directory must not be a symlink");
    const rootPath = await realpath(root);
    let current = rootPath;
    for (let i = -1; i < parts.length; i++) {
      if (i >= 0) {
        await verify();
        current = join(current, parts[i]!);
      }
      const parent = held.at(-1);
      const location =
        parent && process.platform === "linux"
          ? `/proc/self/fd/${parent.handle.fd}/${parts[i]}`
          : current;
      if (i >= 0 && create)
        await mkdir(location, { mode: 0o700 }).catch((error) => {
          if (error.code !== "EEXIST") throw error;
        });
      const handle = await open(
        location,
        constants.O_RDONLY |
          (constants.O_DIRECTORY ?? 0) |
          (constants.O_NOFOLLOW ?? 0) |
          (constants.O_NONBLOCK ?? 0),
      );
      const identity = await handle.stat().catch(async (error) => {
        await handle.close();
        throw error;
      });
      held.push({ path: current, handle, identity });
      if (!identity.isDirectory() || (i === -1 && !sameResourceIdentity(identity, original)))
        throw new Error("Resource directory changed while it was opened");
    }
    await verify();
    const parent = held.at(-1)!;
    const location = (file: string) =>
      process.platform === "linux"
        ? `/proc/self/fd/${parent.handle.fd}/${file}`
        : join(parent.path, file);
    return {
      name,
      path: location(name),
      location,
      rootIdentity: held[0]!.identity,
      rootPath,
      identities: held.map(({ identity }) => ({ dev: identity.dev, ino: identity.ino })),
      verify,
      close,
    };
  } catch (error) {
    await close();
    throw error;
  }
}

/** Trusted Host binding. Resource requests never accept a guest-supplied scope. */
export interface ResourceScope {
  appId: string;
  projectPath: string;
}

/** Stable compatibility shape: existing asset IDs and records remain unchanged. */
export interface ResourceAsset {
  id: string;
  name: string;
  mimeType: string;
  bytes: number;
  sha256: string;
  createdAt: number;
}

/** Mutable external storage is a reference, never an immutable content digest. */
export interface ExternalResourceReference {
  id: string;
  kind: "external";
  name: string;
  mimeType: string;
  bytes: number;
  lastModified: number;
  createdAt: number;
  state: "available" | "missing" | "changed";
}
export type MediaScope = ResourceScope;
export type MediaAsset = ResourceAsset;

const CHUNK_BYTES = 32768;
export interface PanelResourceServiceOptions {
  rootDirectory: string;
  isScopeAuthorized(scope: ResourceScope): boolean | Promise<boolean>;
  maxFileBytes?: number;
}
export interface PanelResourceCallContext {
  /** Resolve a live, owner-authorized process directory grant; never accept a guest path. */
  resolveDirectory?: (handle: string) => string | Promise<string>;
  signal?: AbortSignal;
}
export class PanelResourceError extends Error {
  constructor(
    readonly code: "INVALID_RESOURCE_REQUEST" | "RESOURCE_ACCESS_DENIED" | "RESOURCE_IO_FAILED",
    message: string,
    options?: ErrorOptions,
  ) {
    super(message, options);
    this.name = "PanelResourceError";
  }
}
function object(value: unknown, keys: string[]): Record<string, any> {
  if (
    !value ||
    typeof value !== "object" ||
    Array.isArray(value) ||
    Object.keys(value).some((key) => !keys.includes(key))
  )
    throw new PanelResourceError("INVALID_RESOURCE_REQUEST", "Invalid resource request fields");
  return value as Record<string, any>;
}
function integer(value: unknown, min: number, max: number): number {
  if (!Number.isSafeInteger(value) || Number(value) < min || Number(value) > max)
    throw new PanelResourceError(
      "INVALID_RESOURCE_REQUEST",
      "Invalid resource byte range or limit",
    );
  return Number(value);
}
function assetId(value: unknown): string {
  if (typeof value !== "string" || !/^(?:asset|external)-[a-f0-9]{64}$/.test(value))
    throw new PanelResourceError("INVALID_RESOURCE_REQUEST", "Invalid resource ID");
  return value;
}

/** Generic resource custody and byte transport; it never interprets a project or invokes a model. */
export class PanelResourceService {
  readonly library: ResourceLibrary;
  readonly references: ExternalResourceReferences;
  private readonly uploads: ResourceUploadIngest;
  private readonly directoryIdentities = new Map<string, { dev: number; ino: number }>();
  private closed = false;
  constructor(private readonly options: PanelResourceServiceOptions) {
    this.library = new ResourceLibrary(options);
    this.references = new ExternalResourceReferences(options);
    this.uploads = new ResourceUploadIngest({ ...options, library: this.library });
  }
  capabilities() {
    return {
      available: true,
      maxChunkBytes: CHUNK_BYTES,
      maxFileBytes: this.options.maxFileBytes ?? 20 * 1024 ** 3,
      materialize: true,
      capture: true,
      resumableUploads: true,
      externalReferences: true,
      createReferences: true,
    };
  }
  initialize(): Promise<void> {
    return this.uploads.initialize();
  }
  private async authorize(scope: ResourceScope, context: PanelResourceCallContext = {}) {
    normalizeMediaScope(scope);
    context.signal?.throwIfAborted();
    if (this.closed || !(await this.options.isScopeAuthorized(scope)))
      throw new PanelResourceError(
        "RESOURCE_ACCESS_DENIED",
        "Resource access is no longer authorized",
      );
    context.signal?.throwIfAborted();
  }
  private async directory(
    scope: ResourceScope,
    input: Record<string, any>,
    context: PanelResourceCallContext,
    create: boolean,
  ) {
    if (
      typeof input.directoryHandle !== "string" ||
      !input.directoryHandle ||
      input.directoryHandle.length > 256 ||
      !context.resolveDirectory
    )
      throw new PanelResourceError(
        "INVALID_RESOURCE_REQUEST",
        "An authorized tool directory is required",
      );
    const path = resourceRelativePath(input.path);
    const root = await context.resolveDirectory(input.directoryHandle);
    const verify = async () => {
      await this.authorize(scope, context);
      if ((await context.resolveDirectory!(input.directoryHandle)) !== root)
        throw new PanelResourceError(
          "RESOURCE_ACCESS_DENIED",
          "Tool directory authorization changed",
        );
    };
    const held = await openResourceDirectory(root, path, create, verify);
    const key = `${mediaScopeKey(scope)}:${input.directoryHandle}`;
    const previous = this.directoryIdentities.get(key);
    if (previous && !sameResourceIdentity(previous, held.rootIdentity)) {
      await held.close();
      throw new PanelResourceError("RESOURCE_ACCESS_DENIED", "Tool directory has been replaced");
    }
    // Grants are bounded by the Host; retain a bounded extra identity cache as defence in depth.
    if (this.directoryIdentities.size >= 1024 && !previous) {
      await held.close();
      throw new Error("Too many resource directory grants; reopen the panel");
    }
    this.directoryIdentities.set(key, { dev: held.rootIdentity.dev, ino: held.rootIdentity.ino });
    return { ...held, root };
  }
  async get(scope: ResourceScope, id: string): Promise<ResourceAsset | ExternalResourceReference> {
    await this.authorize(scope);
    return assetId(id).startsWith("external-")
      ? this.references.get(scope, id)
      : this.library.get(scope, id);
  }
  async openRead(
    scope: ResourceScope,
    id: string,
    options: { range?: string; method?: string; signal?: AbortSignal } = {},
  ): Promise<MediaReadResult> {
    await this.authorize(scope, options);
    return assetId(id).startsWith("external-")
      ? this.references.openRead(scope, id, options)
      : this.library.openRead(scope, id, options);
  }
  private async reference(
    scope: ResourceScope,
    raw: unknown,
    context: PanelResourceCallContext,
    relink = false,
  ) {
    const input = object(
      raw,
      relink
        ? ["id", "directoryHandle", "path"]
        : ["directoryHandle", "path", "name", "mimeType", "expectedBytes", "expectedLastModified"],
    );
    if (
      (input.name !== undefined &&
        (typeof input.name !== "string" || !input.name || input.name.length > 240)) ||
      (input.mimeType !== undefined &&
        (typeof input.mimeType !== "string" || !input.mimeType || input.mimeType.length > 200))
    )
      throw new PanelResourceError(
        "INVALID_RESOURCE_REQUEST",
        "Invalid external reference metadata",
      );
    const directory = await this.directory(scope, input, context, false);
    try {
      const options = {
        name: input.name,
        mimeType: input.mimeType,
        expectedBytes: input.expectedBytes,
        expectedLastModified: input.expectedLastModified,
        signal: context.signal,
        assertAuthorized: directory.verify,
      };
      return {
        reference: relink
          ? await this.references.relinkFromDirectory(
              scope,
              input.id,
              directory.root,
              input.path,
              options,
            )
          : await this.references.createFromDirectory(scope, directory.root, input.path, options),
      };
    } finally {
      await directory.close();
    }
  }
  private async materialize(
    scope: ResourceScope,
    raw: unknown,
    context: PanelResourceCallContext,
    cloneManaged = true,
  ): Promise<{ assetId: string; path: string; bytes: number; sha256: string }> {
    const input = object(raw, ["assetId", "directoryHandle", "path"]);
    const asset = await this.get(scope, assetId(input.assetId));
    const directory = await this.directory(scope, input, context, true);
    let temporary = directory.location(`.${randomUUID()}.resource-partial`);
    let clone: Awaited<ReturnType<typeof stageResourceClone>>;
    let destination: Awaited<ReturnType<typeof open>> | undefined;
    let published = false;
    let identity: { dev: number; ino: number } | undefined;
    try {
      await directory.verify();
      if (cloneManaged && "sha256" in asset) {
        const sourcePath = await this.library.resolvePath(scope, asset.id);
        const stagingDirectory = await mediaDirectory(this.options.rootDirectory, [
          "scopes",
          mediaScopeKey(scope),
          "materialize",
        ]);
        clone = await stageResourceClone({
          sourcePath,
          stagingDirectory,
          targetDevice: directory.identities.at(-1)!.dev,
          verify: directory.verify,
          signal: context.signal,
        });
      }
      if (clone) {
        temporary = clone.path;
        destination = clone.handle;
      } else {
        destination = await open(
          temporary,
          constants.O_RDWR | constants.O_CREAT | constants.O_EXCL | (constants.O_NOFOLLOW ?? 0),
          0o600,
        );
      }
      identity = await destination.stat();
      let sha256: string;
      if (clone && "sha256" in asset) {
        sha256 = asset.sha256;
      } else {
        const source = await this.openRead(scope, asset.id, { signal: context.signal });
        const hash = createHash("sha256");
        let bytes = 0;
        try {
          for await (const chunk of source.body!) {
            await directory.verify();
            if (bytes + chunk.length > asset.bytes) throw new Error("Resource content changed");
            hash.update(chunk);
            let offset = 0;
            while (offset < chunk.length) {
              const written = await destination.write(
                chunk,
                offset,
                chunk.length - offset,
                bytes + offset,
              );
              if (!written.bytesWritten) throw new Error("Resource copy stopped making progress");
              offset += written.bytesWritten;
            }
            bytes += chunk.length;
          }
        } finally {
          source.body?.destroy();
        }
        sha256 = hash.digest("hex");
        if (bytes !== asset.bytes || ("sha256" in asset && sha256 !== asset.sha256))
          throw new Error("Resource content failed integrity validation");
      }
      await destination.sync();
      // A tool may share the granted directory. Verify the actual destination,
      // not only the source stream, before publishing the materialized file.
      const completed = await destination.stat();
      const copiedHash = createHash("sha256");
      const buffer = Buffer.allocUnsafe(256 * 1024);
      for (let offset = 0; offset < asset.bytes; ) {
        await directory.verify();
        const read = await destination.read(
          buffer,
          0,
          Math.min(buffer.length, asset.bytes - offset),
          offset,
        );
        if (!read.bytesRead) throw new Error("Resource copy was truncated");
        copiedHash.update(buffer.subarray(0, read.bytesRead));
        offset += read.bytesRead;
      }
      const verified = await destination.stat();
      if (
        verified.size !== asset.bytes ||
        verified.mtimeMs !== completed.mtimeMs ||
        verified.ctimeMs !== completed.ctimeMs ||
        copiedHash.digest("hex") !== sha256
      )
        throw new Error("Materialized resource failed integrity verification");
      await clone?.verify();
      await destination.close();
      destination = undefined;
      await directory.verify();
      // Hard-link publication is atomic and refuses to overwrite any existing tool file.
      await link(temporary, directory.path);
      published = true;
      await directory.verify();
      const current = await lstat(directory.path);
      if (!current.isFile() || current.isSymbolicLink() || !sameResourceIdentity(current, identity))
        throw new Error("Resource output changed during publication");
      return { assetId: asset.id, path: input.path, bytes: asset.bytes, sha256 };
    } catch (error) {
      if (published && identity) {
        const current = await lstat(directory.path).catch(() => undefined);
        if (current && sameResourceIdentity(current, identity))
          await rm(directory.path, { force: true }).catch(() => {});
      }
      // Different bind mounts can share st_dev yet refuse hard links. Retry
      // with a temporary file inside the target grant, after releasing this
      // private clone and all held descriptors in finally.
      if (!(clone && !published && (error as NodeJS.ErrnoException).code === "EXDEV")) throw error;
    } finally {
      await destination?.close().catch(() => {});
      const current = await lstat(temporary).catch(() => undefined);
      if (current && identity && sameResourceIdentity(current, identity))
        await rm(temporary, { force: true }).catch(() => {});
      await clone?.close();
      await directory.close();
    }
    return this.materialize(scope, raw, context, false);
  }
  private async capture(scope: ResourceScope, raw: unknown, context: PanelResourceCallContext) {
    const input = object(raw, [
      "directoryHandle",
      "path",
      "name",
      "mimeType",
      "expectedBytes",
      "expectedSha256",
    ]);
    if (
      input.name !== undefined &&
      (typeof input.name !== "string" || !input.name || input.name.length > 240)
    )
      throw new Error("Invalid resource name");
    if (
      input.mimeType !== undefined &&
      (typeof input.mimeType !== "string" || input.mimeType.length > 200)
    )
      throw new Error("Invalid resource MIME type");
    const directory = await this.directory(scope, input, context, false);
    let source: Awaited<ReturnType<typeof open>> | undefined;
    try {
      await directory.verify();
      source = await open(
        directory.path,
        constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0) | (constants.O_NONBLOCK ?? 0),
      );
      const initial = await source.stat();
      if (!initial.isFile()) throw new Error("Tool output must be a regular file");
      const verify = async () => {
        await directory.verify();
        const current = await lstat(directory.path);
        if (current.isSymbolicLink() || !sameResourceIdentity(initial, current))
          throw new Error("Tool output was replaced");
      };
      return {
        asset: await this.library.importFile(scope, directory.path, {
          name: input.name ?? directory.name,
          mimeType: input.mimeType,
          expectedBytes: input.expectedBytes,
          expectedSha256: input.expectedSha256,
          expectedSource: mediaSourceIdentity(initial),
          signal: context.signal,
          assertAuthorized: verify,
        }),
      };

async dispatch(
  scope: ResourceScope,
  method: string,
  raw: unknown = {},
  context: PanelResourceCallContext = {},
): Promise<any> {
  try {
    await this.authorize(scope, context);
    switch (method) {
      case "resources.list": {
        const input = object(raw, ["offset", "limit"]);
        const offset = integer(input.offset ?? 0, 0, 100000),
          limit = integer(input.limit ?? 50, 1, 100);
        const assets = await this.library.list(scope);
        return { assets: assets.slice(offset, offset + limit), total: assets.length };
      }
      case "resources.get":
        return { asset: await this.get(scope, assetId(object(raw, ["id"]).id)) };
      case "resources.references.create":
        return await this.reference(scope, raw, context);
      case "resources.references.get":
        return { reference: await this.references.get(scope, object(raw, ["id"]).id) };
      case "resources.references.relink":
        return await this.reference(scope, raw, context, true);
      case "resources.references.forget":
        return await this.references.forget(scope, object(raw, ["id"]).id);
      case "resources.read":
        return await this.read(scope, raw, context);
      case "resources.materialize":
        return await this.materialize(scope, raw, context);
      case "resources.capture":
        return await this.capture(scope, raw, context);
      case "resources.upload.begin":
        return await this.uploads.begin(scope, raw);
      case "resources.upload.write":
        return await this.uploads.write(scope, raw);
      case "resources.upload.get":
        return await this.uploads.get(scope, raw);
      case "resources.upload.finish":
        return await this.uploads.finish(scope, raw, context.signal);
      case "resources.upload.cancel":
        return await this.uploads.cancel(scope, raw);
      default:
        throw new PanelResourceError("INVALID_RESOURCE_REQUEST", "Unsupported resource method");
    }
  } catch (error) {
    if (
      error instanceof PanelResourceError ||
      (error instanceof Error && error.name === "AbortError")
    )
      throw error;
    throw new PanelResourceError(
      "RESOURCE_IO_FAILED",
      "Resource operation failed; check the file and its authorization, then retry",
      { cause: error },
    );
  }
}

export interface MediaSourceIdentity {
  dev: number;
  ino: number;
  size: number;
  mtimeMs: number;
  ctimeMs: number;
}

export function mediaSourceIdentity(info: MediaSourceIdentity): MediaSourceIdentity {
  return {
    dev: info.dev,
    ino: info.ino,
    size: info.size,
    mtimeMs: info.mtimeMs,
    ctimeMs: info.ctimeMs,
  };
}

export interface MediaReadResult {
  status: 200 | 206 | 405 | 416;
  headers: Record<string, string>;
  body: Readable | null;
}

export function resourceName(value: string): string {
  return (
    basename(value)
      .replace(/[\x00-\x1f\x7f]/g, "_")
      .slice(0, 240) || "media"
  );
}

function assetRecord(raw: unknown, id: string): MediaAsset {
  const value = raw as Partial<MediaAsset> | null;
  if (
    !value ||
    value.id !== id ||
    !ASSET_ID.test(id) ||
    value.sha256 !== id.slice(6) ||
    typeof value.name !== "string" ||
    value.name !== resourceName(value.name) ||
    !SAFE_MIME_TYPES.has(value.mimeType!) ||
    !Number.isSafeInteger(value.bytes) ||
    value.bytes! <= 0 ||
    !Number.isSafeInteger(value.createdAt) ||
    value.createdAt! < 0
  )
    throw new Error("Invalid stored media asset");
  return {
    id,
    name: value.name,
    mimeType: value.mimeType!,
    bytes: value.bytes!,
    sha256: value.sha256!,
    createdAt: value.createdAt!,
  };
}

export class ResourceLibrary {
  private readonly root: string;
  private readonly maxFileBytes: number;
  private readonly now: () => number;
  private readonly isScopeAuthorized?: MediaLibraryOptions["isScopeAuthorized"];
  private readonly writes = new Map<string, Promise<unknown>>();

  constructor(options: MediaLibraryOptions) {
    this.root = options.rootDirectory;
    this.maxFileBytes = options.maxFileBytes ?? 20 * 1024 ** 3;
    this.now = options.now ?? Date.now;
    this.isScopeAuthorized = options.isScopeAuthorized;
    if (!Number.isSafeInteger(this.maxFileBytes) || this.maxFileBytes <= 0)
      throw new Error("Invalid media file budget");
  }

  private async authorize(scope: MediaScope): Promise<void> {
    mediaScopeKey(scope);
    if (this.isScopeAuthorized && !(await this.isScopeAuthorized(scope)))
      throw new Error("Resource authorization was revoked");
  }

  private directory(scope: MediaScope, segments: string[], create = true): Promise<string> {
    return mediaDirectory(
      this.root,
      ["scopes", mediaScopeKey(scope), "assets", ...segments],
      create,
    );
  }

  async importFile(
    scope: MediaScope,
    sourcePath: string,
    options: MediaImportOptions = {},
  ): Promise<MediaAsset> {
    const verify = async () => {
      options.signal?.throwIfAborted();
      await this.authorize(scope);
      await options.assertAuthorized?.();
      options.signal?.throwIfAborted();
    };
    await verify();
    if (
      options.expectedBytes !== undefined &&
      (!Number.isSafeInteger(options.expectedBytes) ||
        options.expectedBytes < 1 ||
        options.expectedBytes > this.maxFileBytes)
    )
      throw new Error("Invalid expected resource size");
    if (options.expectedSha256 !== undefined && !/^[a-f0-9]{64}$/.test(options.expectedSha256))
      throw new Error("Invalid expected resource digest");
    const scopeKey = mediaScopeKey(scope);
    const staging = await mediaDirectory(this.root, ["scopes", scopeKey, "imports"]);
    const stagingIdentity = await lstat(staging);
    const verifyStaging = async () => {
      const currentPath = await mediaDirectory(this.root, ["scopes", scopeKey, "imports"], false);
      const current = await lstat(currentPath);
      if (current.dev !== stagingIdentity.dev || current.ino !== stagingIdentity.ino)
        throw new Error("Resource staging directory changed during import");
    };
    const temporary = join(staging, `${randomUUID()}.partial`);
    const source = await open(
      sourcePath,
      constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0) | (constants.O_NONBLOCK ?? 0),
    );
    let destination: Awaited<ReturnType<typeof open>> | undefined;
    try {
      const initial = await source.stat();
      if (!initial.isFile() || initial.size <= 0 || initial.size > this.maxFileBytes)
        throw new Error("Source must be a nonempty regular file within the media file budget");
      if (
        options.expectedSource &&
        Object.entries(mediaSourceIdentity(initial)).some(
          ([key, value]) => options.expectedSource![key as keyof MediaSourceIdentity] !== value,
        )
      )
        throw new Error("Source changed since it was selected; select the media file again");
      if (options.expectedBytes !== undefined && initial.size !== options.expectedBytes)
        throw new Error("Resource size does not match the expected size");
      const verifySource = async () => {
        await verify();
        await verifyStaging();
        const current = await lstat(sourcePath);
        if (
          current.isSymbolicLink() ||
          Object.entries(mediaSourceIdentity(initial)).some(
            ([key, value]) => current[key as keyof MediaSourceIdentity] !== value,
          )
        )
          throw new Error("Source changed during media import; select the file again");
      };
      await verifySource();
      const digest = createHash("sha256");
      let copied = 0;
      destination = await open(temporary, "wx", 0o600);
      // A bounded 1 MiB buffer amortizes the filesystem identity checks on large
      // imports. Every block still verifies the grant, source and staging path;
      // both descriptors remain open for the final identity checks and fsync.
      const buffer = Buffer.allocUnsafe(Math.min(initial.size, 1024 * 1024));
      while (true) {
        await verifySource();
        const { bytesRead } = await source.read(buffer, 0, buffer.length, copied);
        if (!bytesRead) break;
        if (copied + bytesRead > this.maxFileBytes) throw new Error("Media file budget exceeded");
        digest.update(buffer.subarray(0, bytesRead));
        let written = 0;
        while (written < bytesRead) {
          options.signal?.throwIfAborted();
          const { bytesWritten } = await destination.write(
            buffer,
            written,
            bytesRead - written,
            copied + written,
          );
          if (!bytesWritten) throw new Error("Media copy stopped making progress");
          written += bytesWritten;
        }
        copied += bytesRead;
        try {
          options.onProgress?.(copied, initial.size);
        } catch {
          /* Detached guests do not abort copies. */
        }
      }
      const after = await source.stat();
      if (
        copied !== initial.size ||
        after.size !== initial.size ||
        after.mtimeMs !== initial.mtimeMs ||
        after.ctimeMs !== initial.ctimeMs ||
        after.ino !== initial.ino ||
        after.dev !== initial.dev
      ) {
        throw new Error("Source changed during media import; select the file again");
      }
      await verifySource();
      await destination.sync();
      await destination.close();
      destination = undefined;
      options.signal?.throwIfAborted();
      const sha256 = digest.digest("hex");
      if (options.expectedSha256 !== undefined && options.expectedSha256 !== sha256)
        throw new Error("Resource digest does not match the expected digest");
      const id = `asset-${sha256}`;
      const name = resourceName(options.name ?? sourcePath);
      const mimeType = resourceMimeType(name, options.mimeType);
      const record: MediaAsset = {
        id,
        name,
        mimeType,
        bytes: copied,
        sha256,
        createdAt: this.now(),
      };
      const key = `${scopeKey}:${id}`;
      const operation = (this.writes.get(key) ?? Promise.resolve())
        .catch(() => {})
        .then(async () => {
          await verifySource();
          try {
            const existing = await this.get(scope, id);
            await this.verifyContent(scope, id, verifySource);
            return existing;
          } catch (error) {
            if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
          }
          const parent = await this.directory(scope, []);
          const parentIdentity = await lstat(parent);
          const directory = join(parent, id);
          const committed = join(staging, `${randomUUID()}.commit`);
          let published = false;
          let publishedIdentity: { dev: number; ino: number } | undefined;
          try {
            await mkdir(committed, { mode: 0o700 });
            publishedIdentity = await lstat(committed);
            await rename(temporary, join(committed, "content"));
            await writeMediaJson(join(committed, "asset.json"), record);
            await verifySource();
            const currentParent = await lstat(await this.directory(scope, [], false));
            if (
              currentParent.dev !== parentIdentity.dev ||
              currentParent.ino !== parentIdentity.ino
            )
              throw new Error("Resource storage directory changed during import");
            try {
              await rename(committed, directory);
              published = true;
            } catch (error) {
              if (!["EEXIST", "ENOTEMPTY"].includes((error as NodeJS.ErrnoException).code ?? ""))
                throw error;
              await this.verifyContent(scope, id, verifySource);
              return this.get(scope, id);
            }
            await verify();
            return structuredClone(record);
          } catch (error) {
            if (published && publishedIdentity) {
              const current = await lstat(directory).catch(() => undefined);
              if (current?.dev === publishedIdentity.dev && current?.ino === publishedIdentity.ino)
                await rm(directory, { recursive: true, force: true }).catch(() => {});
            }
            throw error;
          } finally {
            await rm(committed, { recursive: true, force: true }).catch(() => {});
          }
        });
      this.writes.set(key, operation);
      try {
        return await operation;
      } finally {
        if (this.writes.get(key) === operation) this.writes.delete(key);
      }
    } finally {
      await source.close().catch(() => {});
      await destination?.close().catch(() => {});
      await rm(temporary, { force: true }).catch(() => {});
    }
  }

  async get(scope: MediaScope, id: string): Promise<MediaAsset> {
    await this.authorize(scope);
    if (!ASSET_ID.test(id)) throw new Error("Invalid media asset ID");
    const directory = await this.directory(scope, [id], false);
    const result = assetRecord(await readMediaJson(join(directory, "asset.json")), id);
    await this.authorize(scope);
    return result;

async resolvePath(scope: MediaScope, id: string): Promise<string> {
  const asset = await this.get(scope, id);
  const directory = await this.directory(scope, [id], false);
  const path = join(directory, "content");
  const handle = await open(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
  try {
    const info = await handle.stat();
    if (!info.isFile() || info.size !== asset.bytes)
      throw new Error("Stored media content is missing or changed");
  } finally {
    await handle.close();
  }
  return path;

const input = value as ToolInput;
if (!input.request || typeof input.request !== "object" || Array.isArray(input.request))
  throw new Error("Tool request must be an object");
if (
  input.resources !== undefined &&
  (!Array.isArray(input.resources) || input.resources.length > 128)
)
  throw new Error("Too many tool resources");
const paths = new Set<string>();
for (const resource of input.resources ?? []) {
